"""Brute force reference for tiny instances."""
import itertools, json
from fractions import Fraction

def solve(x):
    C=x['commodities']; S=x['snapshots']; E=x['edges']
    nC=len(C); nS=len(S); nE=len(E)
    W=[sum(r['weight'] for r in c['routes']) for c in C]
    eidx={e['id']:i for i,e in enumerate(E)}
    def loads(q):
        L=[Fraction(0)]*nE
        for ci,c in enumerate(C):
            for r in c['routes']:
                amt=Fraction(q[ci]*r['weight'], W[ci])
                for e in r['edges']: L[eidx[e]]+=amt
        return L
    def metric(si,o,q,L):
        m=o['metric']; t=o['target']
        if m=='demand': return Fraction(q[[c['id'] for c in C].index(t)])
        if m=='link': return L[eidx[t]]
        if m=='ingress': return Fraction(sum(q[ci] for ci,c in enumerate(C) if c['source']==t))
        return Fraction(sum(q[ci] for ci,c in enumerate(C) if c['target']==t))
    # enumerate per snapshot
    per=[]
    for si,s in enumerate(S):
        ranges=[range(s['bounds'][ci][0], s['bounds'][ci][1]+1) for ci in range(nC)]
        lst=[]
        for q in itertools.product(*ranges):
            L=loads(q)
            if any(L[eidx[e['id']]] > e['capacity'] for e in E): continue
            bad=set()
            ok=True
            for o in s['observations']:
                v=metric(si,o,q,L)
                if v < o['lower'] or v > o['upper']:
                    if o['domain'] is None: ok=False; break
                    bad.add(o['domain'])
            if ok: lst.append((q,bad))
        per.append(lst)
    if any(len(p)==0 for p in per): return {'status':'infeasible'}
    best=None; F=[]
    for combo in itertools.product(*per):
        faults=set()
        for q,b in combo: faults |= b
        if len(faults) > x['max_faults']: continue
        if best is None or len(faults)<best:
            best=len(faults); F=[(combo,faults)]
        elif len(faults)==best:
            F.append((combo,faults))
    if best is None: return {'status':'infeasible'}
    forced=set(); poss=set()
    for combo,faults in F:
        poss |= faults
        for d in x['domains']:
            if d not in faults: forced.add(d)
    forced = poss & (set(x['domains']) - forced)
    dr=[]; lr=[]; verdicts=[]
    for si in range(nS):
        drow=[]
        for ci in range(nC):
            vals=[combo[si][0][ci] for combo,_ in F]
            drow.append([min(vals),max(vals)])
        dr.append(drow)
        lrow=[]
        for ei in range(nE):
            vals=[loads(combo[si][0])[ei] for combo,_ in F]
            lrow.append([str(min(vals)),str(max(vals))])
        lr.append(lrow)
        ctrl=S[si]['controller']; tol=S[si]['tolerance']
        agree=[all(abs(combo[si][0][ci]-ctrl[ci])<=tol for ci in range(nC)) for combo,_ in F]
        if all(agree): verdicts.append('consistent')
        elif not any(agree): verdicts.append('inconsistent')
        else: verdicts.append('undetermined')
    def mk(combo,faults):
        return {'demands':[list(combo[si][0]) for si in range(nS)],
                'links':[[str(loads(combo[si][0])[ei]) for ei in range(nE)] for si in range(nS)],
                'faults':sorted(faults)}
    unique = all(dr[si][ci][0]==dr[si][ci][1] for si in range(nS) for ci in range(nC))
    w=mk(*F[0])
    alt=None
    if not unique:
        for combo,faults in F[1:]:
            if combo[si][0]!=F[0][0][si][0] for si in []: pass
        for combo,faults in F[1:]:
            if any(combo[si][0][ci]!=F[0][0][si][0][ci] for si in range(nS) for ci in range(nC)):
                alt=mk(combo,faults); break
        if alt is None:
            for combo,faults in F:
                if any(combo[si][0][ci]!=F[0][0][si][0][ci] for si in range(nS) for ci in range(nC)):
                    alt=mk(combo,faults); break
    return {'status':'unique' if unique else 'ambiguous','min_faults':best,
            'faults':{'forced':sorted(forced),'possible':sorted(poss)},
            'demands':dr,'links':lr,'verdicts':verdicts,'witness':w,'alternative':alt,
            'nF':len(F)}
